input.command:
cd /app && cp /tmp/opt/result.tex input.tex && rm -f main.log main.pdf && pdflatex -interaction=nonstopmode main.tex >/tmp/out.txt 2>&1; echo compile_exit=$?; grep -ci "overfull" main.log; ls -l main.pdf; python3 - <<'EOF'
a=open('/tmp/input.orig.tex').read().split(); b=open('/app/input.tex').read().split()
fams=[[w.strip().lower() for w in l.split(',') if w.strip()] for l in open('/app/synonyms.txt') if l.strip()]
assert len(a)==len(b)
def clean(t): return t.strip('.,`\'"-;:?!()').replace('---','').lower()
bad=[]; d=[]
for x,y in zip(a,b):
    if x!=y:
        d.append((x,y))
        if not any(clean(x) in f and clean(y) in f for f in fams): bad.append((x,y))
print('changed',len(d),'invalid',bad); print(d)
EOF
